const item = items[0];
const rawOutput = item.json.output || item.json.text || '{}';

let decision;
try {
  const cleaned = rawOutput
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  decision = JSON.parse(cleaned);
} catch(e) {
  // Default fallback
  decision = {
    agente: 'ORACULO',
    prioridade: 'media',
    justificativa: 'Fallback padrão por erro de parse',
    parametros: {
      setor: item.json.setor || 'restaurante',
      acao: 'analise_geral',
      periodo: 'dia',
      contexto_extra: {}
    }
  };
}

return [{
  json: {
    ...item.json,
    decision,
    agente: decision.agente,
    setor: decision.parametros?.setor || item.json.setor || 'restaurante'
  }
}];

