// Normaliza dados recebidos do webhook Loyverse
const sale = items[0].json;
const lineItems = sale.line_items || sale.items || sale.receipts?.[0]?.line_items || [];
const receiptDate = sale.receipt_date || sale.created_at || new Date().toISOString();
const ownerId = sale.store_id || sale.merchant_id || sale.owner_id;

if (!lineItems.length) {
  return [{ json: { error: 'Nenhum item na venda', raw: sale } }];
}

const salesRecords = lineItems.map(item => ({
  owner_id: ownerId,
  product_name: item.item_name || item.name || 'Produto Desconhecido',
  product_id_loyverse: item.item_id || item.id,
  variant_id: item.variant_id || null,
  quantity: parseFloat(item.quantity) || 1,
  unit_price: parseFloat(item.price) || 0,
  total_price: (parseFloat(item.price) || 0) * (parseFloat(item.quantity) || 1),
  discount_total: parseFloat(item.discount_amount) || 0,
  cost_price: parseFloat(item.cost) || null,
  created_at: receiptDate,
  source: 'loyverse_webhook',
  receipt_number: sale.receipt_number || sale.id
}));

return salesRecords.map(r => ({ json: r }));

const item = items[0];
const rawOutput = item.json.output || item.json.text || item.json.data || item.json;

let parsedData;
try {
  if (typeof rawOutput === 'string') {
    const cleaned = rawOutput
      .replace(/```json\n?/gi, '')
      .replace(/```\n?/g, '')
      .trim();
    parsedData = JSON.parse(cleaned);
  } else {
    parsedData = rawOutput;
  }
} catch(e) {
  parsedData = { raw_output: rawOutput, parse_error: e.message };
}

const finalResponse = {
  success: !parsedData.error,
  timestamp: new Date().toISOString(),
  sistema: 'GastroSense AI',
  versao: '1.0',
  agente_executado: item.json.agente || item.json.decision?.agente || 'desconhecido',
  setor: item.json.setor || 'restaurante',
  owner_id: item.json.owner_id,
  data: parsedData,
  meta: {
    workflow: 'ecossistema-multi-agente-v1',
    execution_id: $execution?.id || 'local'
  }
};

return [{ json: finalResponse }];
